func TestRenderAuditCopiesVerifiedSelectorFields(t *testing.T) {
	a := &RenderAuditAction{logger: zap.NewNop(), open: fakeOpen(`{"contrast":[{"cls":"H3","tag":"H3",
		"selector":".wrap H3","matches":3,"selectorVerified":true,"fg":"rgb(0,0,0)","bg":"rgb(0,0,0)",
		"ratio":1.0,"need":4.5,"px":18,"text":"x"}]}`)}
	res, err := a.Execute(ctx, req)
	if err != nil { t.Fatal(err) }
	got := res.Contrast[0]
	if got.Selector != ".wrap H3" || got.Matches != 3 || !got.SelectorVerified {
		t.Fatalf("selector fields lost in the copy loop: %+v", got)
	}
	if res.Summary.SelectorScheme != "verified/v1" {
		t.Fatalf("scheme must be stamped UNCONDITIONALLY so a clean page still declares capability, got %q",
			res.Summary.SelectorScheme)
	}
}

