func TestIntegrationRenderAuditSelectorComposition(t *testing.T) {
	if os.Getenv("BROWSER_RUNNER_IT") == "" { t.Skip("needs real Chromium") }
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		io.WriteString(w, `<style>body{background:#111}h3,p,div{color:#131313}</style>`+
			`<section class="wrap"><h3>anchored</h3><p class="body-text">classed</p></section><div>orphan</div>`)
	}))
	defer srv.Close()
	res, err := NewRenderAuditAction(zap.NewNop(), nil).Execute(ctx, reqFor(srv.URL))
	if err != nil { t.Fatal(err) }
	bySel := map[string]ContrastFinding{}
	for _, c := range res.Contrast { bySel[c.Selector] = c }
	for _, want := range []string{".wrap H3", "P.body-text"} {
		if c, ok := bySel[want]; !ok || !c.SelectorVerified {
			t.Errorf("want a verified finding for %q, got %+v (all: %v)", want, c, bySel)
		}
	}
	if c, ok := bySel["DIV"]; !ok || c.Matches < 1 {
		t.Errorf("an anchor-free class-less element must file a verified bare tag with its count, got %+v", c)
	}
	for _, c := range res.Contrast {
		if tag, cls, ok := strings.Cut(c.Selector, "."); ok && tag == cls {
			t.Fatalf("TAG.TAG selector reached a finding — the fallback is back in the selector path: %q", c.Selector)
		}
	}
}

